function solve(m, n) {
  const row = new Array(n).fill(1);
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) row[c] += row[c - 1];
  }
  return row[n - 1];
}

function solve(m, n) {
  let res = 1;
  for (let i = 1; i < m; i++) res = (res * (n - 1 + i)) / i;
  return Math.round(res);
}

